    "sub_khanda_name": "ඉත්ථිලිඞ්ගං",
    "sutta_name": "179. ඝතො නාදීනං",
    "sutta_meaning": "**ඝතො**, ඝ සංඥයා කෙරෙන් පර වූ; **නාදීනං**, නා විභක්තිය ආදි කොට ඇති; **එකවචනානං**, එකවචනයන්ට; **ආය**, ආය යනාදේශය වේ.",
    "sutta_type": "ආදෙසවිධාන සූත්‍ර (කච්. 111)",
    "pada_cheda": "ඝතො + නාදීනං (ද්විපද සූත්‍රයකි)",
    "anuvattana": "ආයො, එකවචනානං - 304 (ක. 109) ආය චතුත්ථෙකවචනස්ස තු",
    "vutti": "තතියාදීසු ‘ආය චතුත්ථෙකවචනස්ස තූ’ති ඉතො ‘ආයො, එකවචනාන’න්ති ච වත්තතෙ.<br><br>ඝසඤ්ඤතො ලිඞ්ගස්සාකාරා පරෙසං නාදීනං ස්මිංපරියන්තානං එකවචනානං විභත්තිගණානං ආයාදෙසො හොති. සරලොපපරනයනානි.<br><br>කඤ්ඤාය, කඤ්ඤාහි කඤ්ඤාභි, කඤ්ඤාය, කඤ්ඤානං, කඤ්ඤාය, කඤ්ඤාහි කඤ්ඤාභි, කඤ්ඤාය, කඤ්ඤානං.",
    "vutti_sanna": "**තතියාදීසු**, තතියාදි විභක්ති විෂයයෙහි; **ආය චතුත්ථෙකවචනස්ස තූති ඉතො**, ‘ආය චතුත්ථෙකවචනස්ස තු’ සූත්‍රයෙන්; **ආයො එකවචනානන්ති ච**, ආයො යනු ද (විභක්ති විපර්යාසයෙන්) එකවචනානං යනු ද; **වත්තතෙ**, වැටේ.<br><br>**ඝසඤ්ඤතො**, ඝ සංඥා ඇති; **ලිඞ්ගස්ස ආකාරා පරෙසං**, ලිඞ්ගයාගේ අන්ත ආකාරයා කෙරෙන් පර වූ; **නාදීනං**, නා විභක්තිය මුල් කොට ඇති; **ස්මිංපරියන්තානං**, ස්මිං විභක්තිය පර්යන්ත කොට ඇති; **එකවචනානං**, එකවචනයන්ගේ; **විභත්තිගණානං**, විභක්ති සමූහයන්ට; **ආයාදෙසො හොති**, ආය යන ආදේශය වේ; **සරලොපපරනයනානි**, සරලොපය හා පරනයනය වෙත්; **කඤ්ඤාය**, කන්‍යාව විසින්.",
    "shadakara": {
      "sambandha_pali": "තතියාදීසු ‘ආයො, එකවචනාන’න්ති ච වත්තමානෙ ඝතො නාදීනං ආයාදෙසවිධානත්ථං ඉදමාහාති අයමිහ සම්බන්ධො.",
      "sambandha": "තතියාදි විභක්තීන්හි ‘ආයො, එකවචනානං’ අනුවර්තනය වන කල්හි ඝ සංඥයා කෙරෙන් පර නාදි විභක්තීන්ට ආය ආදේශ විධානය පිණිස මෙම සූත්‍රය වදාරන ලදී.",
      "pada_pali": "ඝතො, නාදීනන්ති ද්වෙ පදානි.",
      "pada": "ඝතො, නාදීනං යනුවෙන් පද දෙකකි.",
      "padattha_pali": "ඝසඤ්ඤතො පරෙසං නාදීනං ස්මිංපරියන්තානං එකවචනානං ආයාදෙසො හොතීති අත්ථො.",
      "padattha": "ඝ සංඥයා කෙරෙන් පර වූ නා සිට ස්මිං දක්වා වූ එකවචනයන්ට ආය ආදේශය වේ යනු අර්ථයි.",
      "padaviggaha_pali": "නා ආදි යෙසං තෙ නාදයො, තෙසං නාදීනං.",
      "padaviggaha": "නා විභක්තිය ආදි කොට ඇත්තෝ නාදයො නම්; ඔවුන්ට නාදීනං.",
      "chodana_pali": "නාදීනන්ති වුත්තෙ කිං බහුවචනානම්පි ගහණං?",
      "chodana": "‘නාදීනං’ යයි කී කල්හි බහුවචනයන් ද ගැනේද?",
      "parihara_pali": "න ගය්හන්ති, ‘එකවචනාන’න්ති අනුවත්තනතො. තෙන කඤ්ඤාහි කඤ්ඤානන්තිආදීසු න හොති.",
      "parihara": "නොගැනේ; ‘එකවචනානං’ අනුවර්තනය වන හෙයිනි. එබැවින් කඤ්ඤාහි, කඤ්ඤානං ආදියෙහි ආය ආදේශය නොවේ."
    },
    "extended_commentary": "<p>නා / ස / ස්මා / ස / ස්මිං → ආය</p><p>ස්මිං විභක්තියට ‘ඝපතො ස්මිං යං වා’ (180) සූත්‍රයෙන් යං ආදේශය නොවූ පක්ෂයෙහි මෙයින් ආය ආදේශය වේ — කඤ්ඤාය.</p>",
