    "sutta_name": "180. ඝපතො ස්මිං යං වා",
    "sutta_meaning": "**ඝපතො**, ඝ සංඥ ප සංඥයන් කෙරෙන් පර වූ; **ස්මිං**, ස්මිං වචනය; **වා**, විකල්පයෙන්; **යං**, යං යනාදේශය වේ.",
    "sutta_type": "ආදෙසවිධාන සූත්‍ර (කච්. 216)",
