      "pada_pali": "ඝපතො, ස්මිං, යං, වාති චත්තාරි පදානි.",
      "pada": "ඝපතො, ස්මිං, යං, වා යනුවෙන් පද සතරකි.",
      "padattha_pali": "ඝපතො පරස්ස ස්මිංවචනස්ස යං හොති වාති අත්ථො.",
      "padattha": "ඝ ප සංඥයන් කෙරෙන් පර වූ ස්මිං වචනයට විකල්පයෙන් යං ආදේශය වේ යනු අර්ථයි.",
      "padaviggaha_pali": "ඝො ච පො ච ඝපා, තතො ඝපතො.",
