    "counter_examples": "ස්ත්‍රීලිඞ්ග නොවන ඉවර්ණ උවර්ණාන්තයන්ට ප සංඥාව නොවේ; ඒවා ඣ ල සංඥක වේ: අග්ගයො, භික්ඛවො.",
