    "pada_cheda": "අං + යං + ඊතො + පසඤ්ඤතො (චතුප්පද සූත්‍රයකි)",
    "anuvattana": "වා - 180 (ක. 216) ඝපතො ස්මිං යං වා",
    "vutti": "සම්බොධනෙ ‘ඣලපා රස්ස’න්ති (152) රස්සත්තං.<br>භොති ඉත්ථි, භොතියො ඉත්ථී ඉත්ථියො.<br><br>දුතියෙකවචනෙ ‘ඝපතො ස්මිං යං වා’ති ඉතො ‘වා’ති වත්තතෙ.<br><br>පසඤ්ඤතො ඊකාරතො පරස්ස අංවචනස්ස යං හොති වා.<br><br>ඉත්ථියං ඉත්ථිං, ඉත්ථී ඉත්ථියො, ඉත්ථියා, ඉත්ථීහි ඉත්ථීභි,<br>ඉත්ථියා, ඉත්ථීනං,<br>ඉත්ථියා, ඉත්ථීහි ඉත්ථීභි,<br>ඉත්ථියා, ඉත්ථීනං,<br>ඉත්ථියං ඉත්ථියා, ඉත්ථීසු.",
    "vutti_sanna": "**සම්බොධනෙ**, ආලපන විෂයයෙහි; **ඣලපා රස්සන්ති**, ‘ඣලපා රස්සං’ සූත්‍රයෙන්; **රස්සත්තං**, (ගපරකල්හි පසංඥය හට) හ්‍රස්ව වේ; **භොති ඉත්ථි**. **දුතියෙකවචනෙ**, දුතියා එකවචනයෙහි; **ඝපතො ස්මිං යං වාති ඉතො වාති වත්තතෙ**, ‘ඝපතො ස්මිං යං වා’ සූත්‍රයෙන් වා යනු වැටේ.<br><br>**පසඤ්ඤතො ඊකාරතො**, ප සංඥා ඇති ඊකාරයා කෙරෙන්; **පරස්ස අංවචනස්ස**, පර වූ අං වචනය හට; **වා**, විකල්පයෙන්; **යං හොති**, යං යන ආදේශය වේ; **ඉත්ථියං ඉත්ථිං**, ස්ත්‍රිය.",
    "shadakara": {
      "sambandha_pali": "දුතියෙකවචනෙ ‘වා’ති වත්තමානෙ පසඤ්ඤතො ඊකාරතො අංවචනස්ස යංආදෙසවිධානත්ථං ඉදමාහාති අයමිහ සම්බන්ධො.",
      "sambandha": "දුතියා එකවචනයෙහි ‘වා’ අනුවර්තනය වන කල්හි ප සංඥක ඊකාරයා කෙරෙන් පර අං වචනයට යං ආදේශය විධානය පිණිස මෙම සූත්‍රය වදාරන ලදී.",
      "pada_pali": "අං, යං, ඊතො, පසඤ්ඤතොති චත්තාරි පදානි.",
      "pada": "අං, යං, ඊතො, පසඤ්ඤතො යනුවෙන් පද සතරකි.",
      "padattha_pali": "පසඤ්ඤතො ඊකාරතො පරස්ස අංවචනස්ස යං හොති වාති අත්ථො.",
      "padattha": "ප සංඥක ඊකාරයා කෙරෙන් පර වූ අං වචනයට විකල්පයෙන් යං ආදේශය වේ යනු අර්ථයි.",
      "padaviggaha_pali": "ඊ එව ඊකාරො, තතො ඊතො. පසඤ්ඤා අස්ස අත්ථීති පසඤ්ඤො, තතො පසඤ්ඤතො.",
      "padaviggaha": "ඊ යනුම ඊකාරය; ඔහු කෙරෙන් ඊතො. ප සංඥාව ඇත්තේ පසඤ්ඤ නම්; ඔහු කෙරෙන් පසඤ්ඤතො.",
      "chodana_pali": "ඊතොති කිමත්ථං?",
      "chodana": "‘ඊතො’ යනු කුමක් පිණිසද?",
      "parihara_pali": "ඉවණ්ණුවණ්ණන්තනිවත්තනත්ථං — රත්තිං, යාගුං, ජම්බුං.",
      "parihara": "ඉකාර, උකාර, ඌකාරාන්තයන් නිවෘත්තිය පිණිසයි — රත්තිං, යාගුං, ජම්බුං (යං ආදේශ නොවේ)."
    },
    "extended_commentary": "<p>....ඊ (ප) + අං → යං</p><p>ඉත්ථියං යන තන්හි පසංඥක ඊකාරයා කෙරෙන් පර වූ අං වචනය හට යං ආදේශ කළ කල්හි ‘අඝො රස්සමෙකවචනයොස්වපි ච’ (144) සූත්‍රයෙන් හ්‍රස්ව කටයුතු (සන්නය).</p>",
