    "sutta_name": "190. ණව ණික ණෙය්‍ය ණන්තුහි",
    "sutta_meaning": "**ඉත්ථියං**, ස්ත්‍රීලිඞ්ගයෙහි පවත්නා වූ; **ණවණිකණෙය්‍යණන්තූහි**, ණව ප්‍රත්‍යයාන්තය, ණික ප්‍රත්‍යයාන්තය, ණෙය්‍ය ප්‍රත්‍යයාන්තය, ණ ප්‍රත්‍යයාන්තය, න්තු ප්‍රත්‍යයාන්තය (-වන්තු, -මන්තු) යන මේ ශබ්දයන් කෙරෙන් පරව; **වා**, විකල්පයෙන්; **ඊප්පච්චයො**, ඊ ප්‍රත්‍යය වේ.",
    "sutta_type": "පච්චයවිධාන සූත්‍ර (ප්‍රත්‍යය විධි) (කච්. 239)",
    "pada_cheda": "ණවණිකණෙය්‍යණන්තූහි (ඒකපද සූත්‍රයකි)",
    "anuvattana": "ඉත්ථියං, පච්චයො - 176 (ක. 237) ඉත්ථියමතො ආප්පච්චයො; වා, ඊ - 187 (ක. 238) නදාදිතො වා ඊ",
    "vutti": "‘මානව’ඉතීධ ‘ඉත්ථියං, වා, ඊ’ති ච වත්තතෙ.<br><br>ණව ණික ණෙය්‍ය ණ-න්තුප්පච්චයන්තෙහි ඉත්ථියං වත්තමානෙහි ලිඞ්ගෙහි ඊප්පච්චයො හොති. වාධිකාරො කත්ථචි නිවත්තනත්ථො, සරලොපාදි. මානවී, එවං නාවිකී, වෙනතෙය්‍යී, ගොතමී.",
    "vutti_sanna": "**මානව ඉති ඉධ**, මානව යන මෙහි; **ඉත්ථියං වා ඊති ච වත්තතෙ**, ‘ඉත්ථියමතො ආප්පච්චයො’ සූත්‍රයෙන් ඉත්ථියං යනු ද, ‘නදාදිතො වා ඊ’ සූත්‍රයෙන් වා යනු ද ඊ යනු ද වැටේ.<br><br>**ණව ණික ණෙය්‍ය ණ න්තුප්පච්චයන්තෙහි**, ණව, ණික, ණෙය්‍ය, ණ, න්තු යන ප්‍රත්‍යයන් අන්ත කොට ඇති; **ඉත්ථියං වත්තමානෙහි ලිඞ්ගෙහි**, ස්ත්‍රීලිඞ්ගයෙහි වැටෙන්නා වූ ශබ්දයන් කෙරෙන් පරව; **ඊප්පච්චයො හොති**, ඊ ප්‍රත්‍යය වේ; **වාධිකාරො**, අධිකෘත වා ශබ්දය තෙම; **කත්ථචි නිවත්තනත්ථො**, (‘ථෙරිකා’, ‘පඤ්චසිකා’ යනාදී) කිසි තැනෙක්හි යථෝක්ත ප්‍රත්‍යයාන්තයන් කෙරෙන් ඊ ප්‍රත්‍යයාගේ නිවෘත්තිය පිණිසයි; **සරලොපාදි**, සරලොපාදිය වේ; **මානවී**, මනුෂ්‍ය ස්ත්‍රිය; **එවං**, මෙසේ; **නාවිකී**, නාවිකාවිය; **වෙනතෙය්‍යී**, ගුරුළු දෙන; **ගොතමී**, ගෞතම ගෝත්‍රයෙහි උපන්නිය.",
    "shadakara": {
      "sambandha_pali": "මානවඉතීධ ‘ඉත්ථියං, වා, ඊ’ති ච වත්තමානෙ ණවාදිප්පච්චයන්තෙහි ඊප්පච්චයවිධානත්ථං ඉදමාහාති අයමිහ සම්බන්ධො.",
      "sambandha": "මානව යන මෙහි ‘ඉත්ථියං, වා, ඊ’ අනුවර්තනය වන කල්හි ණව ආදි ප්‍රත්‍යයාන්තයන්ගෙන් ඊ ප්‍රත්‍යය විධානය පිණිස මෙම සූත්‍රය වදාරන ලදී.",
      "pada_pali": "ණවණිකණෙය්‍යණන්තූහීති එකං පදං.",
      "pada": "ණවණිකණෙය්‍යණන්තූහි යනුවෙන් එක් පදයකි.",
      "padattha_pali": "ණවණිකණෙය්‍යණන්තුප්පච්චයන්තෙහි ඉත්ථියං වත්තමානෙහි ලිඞ්ගෙහි ඊප්පච්චයො හොතීති අත්ථො.",
      "padattha": "ස්ත්‍රීලිඞ්ගයෙහි පවත්නා ණව, ණික, ණෙය්‍ය, ණ, න්තු ප්‍රත්‍යයාන්ත ලිඞ්ගයන් කෙරෙන් ඊ ප්‍රත්‍යය වේ යනු අර්ථයි.",
      "padaviggaha_pali": "ණවො ච ණිකො ච ණෙය්‍යො ච ණො ච න්තු ච ණවණිකණෙය්‍යණන්තවො, තෙහි ණවණිකණෙය්‍යණන්තූහි.",
      "padaviggaha": "ණව ද ණික ද ණෙය්‍ය ද ණ ද න්තු ද ණවණිකණෙය්‍යණන්තු නම්; ඔවුන් කෙරෙන් ණවණිකණෙය්‍යණන්තූහි.",
      "chodana_pali": "‘නදාදිතො වා ඊ’ති සිද්ධෙ කිමත්ථමිදං? වාධිකාරො ච කිමත්ථො?",
      "chodana": "‘නදාදිතො වා ඊ’ සූත්‍රයෙන් සිද්ධ කල්හි මෙය කුමට ද? වා අධිකාරය කුමට ද?",
      "parihara_pali": "ණවාදිප්පච්චයන්තෙහි නියමෙන ඊප්පච්චයවිධානත්ථං. වාධිකාරො කත්ථචි නිවත්තනත්ථො — ථෙරිකා, පඤ්චසිකා.",
      "parihara": "ණව ආදි ප්‍රත්‍යයාන්තයන්ගෙන් ඊ ප්‍රත්‍යය විධානය පිණිසයි. වා අධිකාරය කිසි තැනෙක්හි නිවෘත්තිය පිණිසයි — ථෙරිකා, පඤ්චසිකා (ආ ප්‍රත්‍යය)."
    },
    "extended_commentary": "<p>මානවී ශබ්දයෙන් මනුෂ්‍යයාගේ දුව ද තරුණාංගනාවන් ද කියත්; නාවිකී ශබ්දයෙන් නාවිකාවියන් කියත්; වෙනතෙය්‍යී ශබ්දයෙන් ගුරුළු දෙනුන් කියත්; ගොතමී ශබ්දයෙන් ගෞතම ගෝත්‍රයෙහි උපන්නිය කියත් (සන්නය).</p>",
