    "sutta_name": "192. භවතො භොතො",
    "sutta_meaning": "**ඊකාරෙ**, ස්ත්‍රීලිඞ්ගයෙහි කරන ලද ඊ ප්‍රත්‍යය පර කල්හි; **භවතො**, සියලුම භවන්ත ශබ්දයට; **භොතො**, භොත යනාදේශ වේ.",
    "sutta_type": "ආදෙසවිධාන සූත්‍ර (කච්. 242)",
