    "anuvattana": "ඊකාරෙ - 191 (ක. 241) න්තුස්ස තමීකාරෙ",
    "vutti": "‘භවන්ත ඊ’ඉතීධ ‘ඊකාරෙ’ති වත්තතෙ.<br><br>සබ්බස්සෙව භවන්තසද්දස්ස භොතාදෙසො හොති ඊකාරෙ ඉත්ථිගතෙ පරෙ.<br><br>සා භොතී, භොතී භොතියො, හෙ භොති, හෙ භොතී භොතියො ඉච්චාදි.",
    "vutti_sanna": "**භවන්ත ඊ ඉති ඉධ**, භවන්ත ඊ යන මෙහි; **ඊකාරෙති ච වත්තතෙ**, ‘න්තුස්ස තමීකාරෙ’ සූත්‍රයෙන් ඊකාරෙ යනු ද වැටේ.<br><br>**සබ්බස්සෙව භවන්තසද්දස්ස**, සියලුම භවන්ත ශබ්දය හට; **ඉත්ථිගතෙ ඊකාරෙ පරෙ**, ස්ත්‍රීලිඞ්ගයෙහි කරන ලද ඊ ප්‍රත්‍යය පර කල්හි; **භොතාදෙසො හොති**, භොත යන ආදේශය වේ; **සා භොතී**, ඒ භවත් ස්ත්‍රිය; **භොතී භොතියො**, භවත් ස්ත්‍රීහු; **හෙ භොති**, භවතියෙනි.",
